package com.csust.eyediagnosis.workflow.persistence.repository;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper; import com.csust.eyediagnosis.workflow.persistence.entity.ExplanationSnapshotEntity; import com.csust.eyediagnosis.workflow.persistence.mapper.ExplanationSnapshotMapper; import org.springframework.stereotype.Repository; import java.time.LocalDateTime; import java.util.Optional;
@Repository public class MybatisExplanationSnapshotRepository implements ExplanationSnapshotRepository { private final ExplanationSnapshotMapper mapper; public MybatisExplanationSnapshotRepository(ExplanationSnapshotMapper mapper){this.mapper=mapper;} public int insert(ExplanationSnapshotEntity e){return mapper.insert(e);} public Optional<ExplanationSnapshotEntity> findByWorkflowIdAndRevision(String id,long revision){return Optional.ofNullable(mapper.selectOne(new LambdaQueryWrapper<ExplanationSnapshotEntity>().eq(ExplanationSnapshotEntity::getWorkflowId,id).eq(ExplanationSnapshotEntity::getRevision,revision)));} public int updatePublicationStatusIfExpected(String workflowId,long revision,String expected,String target){return mapper.update(null,new LambdaUpdateWrapper<ExplanationSnapshotEntity>().set(ExplanationSnapshotEntity::getPublicationStatus,target).set(ExplanationSnapshotEntity::getPublishedAt,"PUBLISHED".equals(target)?LocalDateTime.now():null).eq(ExplanationSnapshotEntity::getWorkflowId,workflowId).eq(ExplanationSnapshotEntity::getRevision,revision).eq(ExplanationSnapshotEntity::getPublicationStatus,expected));} }
